from abc import ABCMeta, abstractmethod


class Condition(object):
    __metaclass__ = ABCMeta

    @abstractmethod
    def __eq__(self, other):
        pass

    @abstractmethod
    def get_name(self):
        pass

    @abstractmethod
    def validate(self, packet):
        pass

    @abstractmethod
    def append_callback(self, callback):
        pass

    @abstractmethod
    def _run_callbacks_for_unused_matchers(self):
        pass

    @abstractmethod
    def _get_final_result(self):
        pass

    @staticmethod
    def _match_packet(matcher, packet):
        if hasattr(matcher, 'match'):
            matcher.match(packet)
        else:
            matcher(packet)

    def finish(self):
        if not self._get_final_result():
            self._run_callbacks_for_unused_matchers()
        return self._get_final_result()


class Verifiable(object):
    __metaclass__ = ABCMeta

    @abstractmethod
    def verify(self, packets):
        pass
